package pool

import (
	"sync"
	"sync/atomic"
	"testing"
	"time"

	"github.com/stretchr/testify/require"
)

// item is a local reusable object carrying the same field kinds as the
// structs generated by cmd/reset.
type item struct {
	i     int
	s     string
	m     map[string]string
	child *item
}

func (it *item) Reset() {
	if it == nil {
		return
	}
	it.i = 0
	it.s = ""
	clear(it.m)
	if it.child != nil {
		(*it.child).Reset()
	}
}

var _ Resettable = (*item)(nil)

// newPool returns a pool whose factory counts how many fresh objects
// it had to build.
func newPool(t *testing.T) (*Pool[*item], *int32) {
	t.Helper()

	var created int32
	p := New(func() *item {
		atomic.AddInt32(&created, 1)
		return &item{}
	})
	return p, &created
}

func TestFactoryProducesWhenEmpty(t *testing.T) {
	p, created := newPool(t)

	s := p.Get()
	require.NotNil(t, s)
	require.Equal(t, int32(1), atomic.LoadInt32(created))

	s.i = 1
	s.s = "dirty"
	p.Put(s)

	s = p.Get()
	require.Equal(t, 0, s.i)
	require.Empty(t, s.s)
	require.Equal(t, int32(1), atomic.LoadInt32(created), "put objects must be reused, not rebuilt")
}

func TestPutResetsDirtyObject(t *testing.T) {
	p, _ := newPool(t)

	got := p.Get()
	got.i = 7
	got.s = "dirty"
	got.m = map[string]string{"k": "v"}
	got.child = &item{i: 9, s: "inner"}

	p.Put(got)

	again := p.Get()
	require.Equal(t, 0, again.i)
	require.Empty(t, again.s)
	require.NotNil(t, again.m)
	require.Len(t, again.m, 0)
	require.NotNil(t, again.child)
	require.Equal(t, 0, again.child.i)
	require.Empty(t, again.child.s)
}

func TestPutGetConcurrent(t *testing.T) {
	p, _ := newPool(t)

	var wg sync.WaitGroup
	for g := 0; g < 8; g++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			for i := 0; i < 200; i++ {
				s := p.Get()
				s.i = g
				s.s = "race"
				time.Sleep(time.Microsecond)
				p.Put(s)
			}
		}()
	}
	wg.Wait()
}
